export const terrains={plaine:{name:'Plaine',icon:'🌾',color:'#a6bf78',cost:1,points:1},montagne:{name:'Montagne',icon:'🏔️',color:'#abb8ad',cost:2,points:3},ville:{name:'Ville',icon:'🏘️',color:'#e7b477',cost:1,points:2},cote:{name:'Côte',icon:'🌊',color:'#83c6cc',cost:1,points:2},camping:{name:'Camping',icon:'⛺',color:'#8fab7c',cost:1,points:2},auberge:{name:'Auberge',icon:'🏡',color:'#d9ad91',cost:1,points:2},col:{name:'Col mythique',icon:'⛰️',color:'#9ea7bd',cost:3,points:6},decouverte:{name:'Découverte',icon:'✨',color:'#cbb57e',cost:1,points:4}};
export const equipment={kit:{name:'Kit réparation',cost:3,desc:'Annule les pannes et crevaisons'},tente:{name:'Tente',cost:4,desc:'Bivouac : +4 énergie au lieu de +2'},gps:{name:'GPS',cost:3,desc:'Annule les erreurs de navigation'},rechaud:{name:'Réchaud',cost:3,desc:'Un repas rend 5 énergie au lieu de 3'},sacoches:{name:'Sacoches',cost:2,desc:'Offre 3 provisions à l’achat'}};
const eventSpecs=[['Vent de face','Le vent ralentit votre progression.',{energy:-1}],['Hospitalité','Un habitant partage son repas.',{food:1}],['Route bucolique','La campagne offre une belle échappée.',{points:2}],['Marché fermier','Une récolte offerte pour la route.',{food:2}],['Ascension difficile','La pente réserve une dernière rampe.',{energy:-1}],['Panorama','Un horizon qui récompense vos efforts.',{points:3}],['Descente','Quelques kilomètres en roue libre.',{energy:1}],['Orage','Vous attendez à l’abri.',{energy:-2}],['Petit travail','Vous donnez un coup de main.',{money:2}],['Voyageurs','Les récits se croisent autour d’un café.',{points:2}],['Auberge accueillante','Une pause bienvenue.',{energy:2}],['Festival','Une fête anime les rues.',{points:3}],['Baignade','Une pause dans les vagues.',{energy:2}],['Route panoramique','La mer accompagne votre étape.',{points:3}],['Vent marin','Une brise vous pousse.',{energy:1}],['Pêcheurs','Un repas vous est offert.',{food:1}],['Crevaison','Une épine impose une réparation.',{money:-1},'kit'],['Casse mécanique','Un réglage réclame du temps.',{energy:-2},'kit'],['Erreur de navigation','Un détour imprévu.',{energy:-1},'gps'],['Autre cycliste','Vous échangez conseils et histoires.',{points:2}],['Découverte inattendue','Un petit chemin mène à une merveille.',{points:3}],['Fruit du chemin','De quoi compléter les provisions.',{food:1}],['Ciel étoilé','Une nuit mémorable.',{points:2}],['Bonne surprise','Un voyageur partage son pique-nique.',{food:1,energy:1}]];
export const events=eventSpecs.map((s,i)=>({id:i,title:s[0],text:s[1],effect:s[2],protect:s[3],terrain:i<16?['plaine','montagne','ville','cote'][Math.floor(i/4)]:'general'}));
export const dirs=[[0,-1],[1,0],[0,1],[-1,0]];export const key=(x,y)=>`${x},${y}`;
export function random(g){g.seed=(Math.imul(g.seed,1664525)+1013904223)>>>0;return g.seed/4294967296;}
export function roads(t){return t.roads.map(d=>(d+t.rotation)%4);}
export function valid(g,t,x,y){if(g.board[key(x,y)])return false;let connects=false;for(let d=0;d<4;d++){let n=g.board[key(x+dirs[d][0],y+dirs[d][1])];if(n){let a=roads(t).includes(d),b=roads(n).includes((d+2)%4);if(a!==b)return false;if(a&&b)connects=true;}}return connects;}
export function spots(g,t){let out=[],seen=new Set();for(const n of Object.values(g.board))for(const [dx,dy]of dirs){let x=n.x+dx,y=n.y+dy,k=key(x,y);if(!seen.has(k)&&valid(g,t,x,y)){out.push({x,y});seen.add(k);}}return out;}
export function makeGame(bike,seed=Date.now()){let g={version:1,seed:seed>>>0,bike,energy:8,food:bike==='randonneur'?5:3,money:5,points:0,turn:1,phase:'place',pos:'0,0',board:{'0,0':{id:0,type:'ville',roads:[0,1,2,3],rotation:0,x:0,y:0}},deck:[],hand:[],visited:['0,0'],steps:0,cols:0,cities:1,discoveries:0,items:[],log:['Votre voyage commence.'],event:null,done:false};let types=[...Array(14).fill('plaine'),...Array(10).fill('montagne'),...Array(8).fill('ville'),...Array(8).fill('cote'),'camping','camping','auberge','auberge','col','col','decouverte'];g.deck=types.map((type,i)=>({id:i+1,type,roads:[[0,2],[0,1],[0,1,2],[0,1,2,3]][Math.floor(random(g)*4)],rotation:0}));for(let i=g.deck.length-1;i>0;i--){let j=Math.floor(random(g)*(i+1));[g.deck[i],g.deck[j]]=[g.deck[j],g.deck[i]];}refill(g);return g;}
function refill(g){while(g.hand.length<3&&g.deck.length)g.hand.push(g.deck.pop());}
export function place(g,index,x,y){if(g.phase!=='place'||g.done||!valid(g,g.hand[index],x,y))return false;let t=g.hand.splice(index,1)[0];g.board[key(x,y)]={...t,x,y};refill(g);g.phase='move';return true;}
export function cost(g,t){return Math.max(1,terrains[t.type].cost-(g.bike==='gravel'&&['montagne','col'].includes(t.type)?1:0));}
export function moves(g){let n=g.board[g.pos];return roads(n).map(d=>g.board[key(n.x+dirs[d][0],n.y+dirs[d][1])]).filter(t=>t&&roads(t).includes((dirs.findIndex(([dx,dy])=>t.x===n.x+dx&&t.y===n.y+dy)+2)%4));}
export function endTurn(g){g.turn++;g.phase='place';if(!g.hand.length&&!g.deck.length)g.done=true;}
export function move(g,k){let t=g.board[k];if(g.done||g.phase!=='move'||!moves(g).includes(t)||g.energy<cost(g,t))return false;g.energy-=cost(g,t);g.pos=k;g.steps++;let first=!g.visited.includes(k);if(first){g.visited.push(k);g.points+=terrains[t.type].points;if(t.type==='col')g.cols++;if(t.type==='ville')g.cities++;if(t.type==='decouverte')g.discoveries++;if(random(g)<.7){let pool=events.filter(e=>e.terrain===t.type||e.terrain==='general'||(t.type==='col'&&e.terrain==='montagne'));g.event=pool[Math.floor(random(g)*pool.length)];g.phase='event';return true;}}endTurn(g);return true;}
export function resolve(g){if(!g.event)return;let e=g.event;if(!g.items.includes(e.protect))for(let [k,v]of Object.entries(e.effect))g[k]=Math.max(0,k==='energy'?Math.min(10,g[k]+v):g[k]+v);g.log.unshift(e.title);g.log=g.log.slice(0,6);g.event=null;endTurn(g);}
export function recover(g,action){if(g.done||g.phase==='event')return false;if(action==='eat'){if(!g.food||g.energy===10)return false;g.food--;g.energy=Math.min(10,g.energy+(g.items.includes('rechaud')?5:3));}else if(action==='rest')g.energy=Math.min(10,g.energy+(g.items.includes('tente')?4:2));else if(action==='food'){if(g.board[g.pos].type!=='ville'||g.money<1)return false;g.money--;g.food+=2;}else if(action==='restaurant'){if(g.board[g.pos].type!=='ville'||g.money<1||g.energy===10)return false;g.money--;g.energy=Math.min(10,g.energy+4);}else if(action==='work'){if(g.board[g.pos].type!=='ville')return false;g.money+=2;}else if(action==='sleep'){if(!['auberge','camping','ville'].includes(g.board[g.pos].type)||g.money<1)return false;g.money--;g.energy=10;}return true;}
export function buy(g,id){let e=equipment[id];if(g.phase==='event'||g.done||g.board[g.pos].type!=='ville'||g.money<e.cost||g.items.includes(id))return false;g.money-=e.cost;g.items.push(id);if(id==='sacoches')g.food+=3;return true;}
export function score(g){return g.points+g.discoveries*3+g.cols*2+g.cities+g.visited.length-1;}
export function rescueHand(g){if(g.phase!=='place')return false;for(let t of g.hand)for(let r=0;r<4;r++)if(spots(g,{...t,rotation:r}).length)return false;for(const n of Object.values(g.board))for(let d of roads(n)){let x=n.x+dirs[d][0],y=n.y+dirs[d][1];if(g.board[key(x,y)])continue;let rs=[];for(let a=0;a<4;a++){let neighbor=g.board[key(x+dirs[a][0],y+dirs[a][1])];if(!neighbor||roads(neighbor).includes((a+2)%4))rs.push(a);}g.hand[0]={...g.hand[0],roads:rs,rotation:0};g.log.unshift('Une route de secours débloque votre main.');return true;}return false;}
